// hyperbolic halfplane distance
float hyperDist(vec2 a, vec2 b){

    vec2 ar = vec2(a.x,-a.y);

    return 2.*log((length(b-a)+length(b-ar))/2./sqrt(a.y*b.y)); 
}


// noise function vec2->vec2
vec2 noise22(vec2 uv){

    vec3 a = fract(uv.xyx*vec3(123.34, 234.34, 345.65));
    a += dot(a, a + 34.45);

    return fract(vec2(a.x * a.y, a.y * a.z));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalize pixel coordinates -1<>1
    vec2 uv = fragCoord/iResolution.y;
        uv.x= uv.x-0.5;

    // time
    float t = 0.2*iTime+100.;

    // draw n randomly positioned points
    float m = 0., 
          n = 80.,
          minDist = 0.5,
          cellIndex = 0.;

    for(float i=0.; i<n; i++){

        vec2 r = noise22(vec2(i+2.)),
             p = sin(r*t);

        float d = hyperDist(uv, p);

        // find minimal distance to a particular point
        if(d<minDist){
            minDist = d;
            cellIndex =i;
        }
    }


    vec3 col = vec3(.9*minDist);
    // output to screen
    fragColor = vec4(col,1.0);
}
